/**
 * Storno objednavky z detailu (POST id, reason).
 *
 * Storno dela novy e-shop: hlida stavy (odeslanou nestornuje), urci castku
 * k vraceni a uvolni rezervace ve skladu. Tady se jen zapise historie.
 */
public function cancelAction()
{
    global $db;
    legacy_db();
    auth_require('obchod');

    $id = $this->post('id');
    $detailUrl = admin_url('order', array('id' => $id));
    if (!is_post()) {
        return $this->redirect($detailUrl);
    }

    $order = $db->one("SELECT id, status FROM orders WHERE id = " . $db->quote($id));
    if ($order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->redirect($detailUrl);
    }

    $reason = trim($this->post('reason'));
    if ($reason == '') {
        $reason = 'storno v administraci';
    }

    try {
        $refund = legacy_dispatch(new CancelOrder(OrderId::fromString($id), $reason));
    } catch (\DomainException $e) {
        flash('Objednávku ve stavu ' . order_state_label($order['status']) . ' nelze stornovat', 'error');

        return $this->redirect($detailUrl);
    }

    audit_log('order', $id, 'storno', array(
        'from'   => $order['status'],
        'reason' => $reason,
        'refund' => $refund->amountInCents,
    ));
    $note = 'Storno: ' . $reason;
    if ($refund->amountInCents > 0) {
        $note .= "\nVrátit zákazníkovi " . format_price($refund->amountInCents, $refund->currency->value);
    }
    $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES (" . $db->quote($id) . ", " . $db->quote(auth_login_name()) . ", " . $db->quote($note) . ", '" . date('Y-m-d H:i:s') . "')");
    cache_delete('dashboard_stats');

    if ($refund->amountInCents > 0) {
        flash('Objednávka stornována, zákazníkovi se vrací ' . format_price($refund->amountInCents, $refund->currency->value));
    } else {
        flash('Objednávka stornována (nebyla zaplacená, nic se nevrací)');
    }

    return $this->redirect($detailUrl);
}

